] at hstep <;>\n            simp at hstep <;> simp [hstep]\n        have hfin : column X (-((n : ℕ) + 1 : ℤ)) t = !(decide (n % 2 = 0)) := by\n          rw [← hval]; congr 1; push_cast; ring\n        push_cast\n        rw [hfin, alt_succ]\n  exact aux j X t L h hj",
